#!/bin/bash
# Run an eidchain node on Linux (also WSL) behind a Cloudflare Tunnel.
#
#   deploy/linux/install.sh render DIR          write every generated file to DIR (review, test)
#   sudo deploy/linux/install.sh packages       nginx from Ubuntu, cloudflared from Cloudflare's apt repo
#   sudo deploy/linux/install.sh install [--seed DATA-DIR]
#   sudo deploy/linux/install.sh uninstall      stop the services; data and keys stay
#
# The Linux counterpart of deploy/macos/install.sh, with the same layout, ports
# and generated nginx and tunnel configs (deploy/tunnel-node.sh), so a node looks
# the same on every host. systemd units take the place of LaunchDaemons.
# deploy/install.sh does not fit here: it is the ivoras.net host, with TLS and
# card login in nginx and no tunnel.
#
# Settings come from deploy/linux/eidchain.env (see eidchain.env.example).
# Build first, as yourself: go build -o bin/eidchain ./cmd/eidchain.
# --seed copies a chain (genesis, config.json, keys) into the data directory on
# the first install; later installs never touch the data.
set -euo pipefail
cd "$(dirname "$0")/../.."
REPO=$PWD

ENV_FILE=${EIDCHAIN_ENV:-deploy/linux/eidchain.env}
[[ -f "$ENV_FILE" ]] || { echo "missing $ENV_FILE: copy deploy/linux/eidchain.env.example" >&2; exit 1; }
# shellcheck source=/dev/null
. "$ENV_FILE"
GENERATOR=deploy/linux/install.sh
# shellcheck source=deploy/tunnel-node.sh
. deploy/tunnel-node.sh

# Cloudflare's package signing key, checked before apt is told to trust it.
CF_KEY_URL=https://pkg.cloudflare.com/cloudflare-public-v2.gpg
CF_KEY_FPR=CC94B39C77AE7342A68B89628A682D308D4E5E73
CF_KEYRING=/usr/share/keyrings/cloudflare-public-v2.gpg

log() { echo "== $*"; }
die() { echo "error: $*" >&2; exit 1; }
unit() { echo "$UNIT_PREFIX-$1.service"; }

services() {
  echo node nginx
  [[ -n "${TUNNEL_ID:-}" ]] && echo tunnel
  return 0
}

# write_unit FILE NAME WORKDIR -- ARGS...
# Each service may write only where it has to. nginx is left out of
# MemoryDenyWriteExecute, which would break PCRE JIT if a config ever turns it on.
write_unit() {
  local file=$1 name=$2 workdir=$3 a exec="" rw families="AF_INET AF_INET6 AF_UNIX" mdwe=true
  shift 4
  for a in "$@"; do
    [[ "$a" =~ [[:space:]\"\'\\%\$] ]] && die "unit argument needs quoting, not supported: $a"
    exec+="${exec:+ }$a"
  done
  case $name in
    node) rw="$PREFIX/data" ;;
    nginx) rw="$PREFIX/state/nginx $PREFIX/logs"; mdwe=false ;;
    tunnel) rw="$PREFIX/state"; families+=" AF_NETLINK" ;;
  esac
  cat >"$file" <<EOF
# Generated by eidchain $GENERATOR. Do not edit; change eidchain.env and re-run.
[Unit]
Description=eidchain $name ($DOMAIN)
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=$SERVICE_USER
Group=$SERVICE_USER
WorkingDirectory=$workdir
ExecStart=$exec
Restart=always
RestartSec=10
TimeoutStopSec=15
StandardOutput=null
StandardError=journal

NoNewPrivileges=true
PrivateTmp=true
PrivateDevices=true
ProtectSystem=strict
ProtectHome=true
ReadWritePaths=$rw
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
RestrictAddressFamilies=$families
RestrictNamespaces=true
LockPersonality=true
MemoryDenyWriteExecute=$mdwe
SystemCallArchitectures=native
CapabilityBoundingSet=
UMask=0027

[Install]
WantedBy=multi-user.target
EOF
}

# render_all ROOT UNITDIR: configs under ROOT (laid out like PREFIX), units in UNITDIR.
render_all() {
  local root=$1 units=$2 peers=() p
  mkdir -p "$root/etc" "$units"
  render_nginx >"$root/etc/nginx.conf"
  if [[ -f /etc/nginx/mime.types ]]; then
    cp /etc/nginx/mime.types "$root/etc/mime.types"
  else
    echo "   note: no /etc/nginx/mime.types yet (install.sh packages); etc/mime.types left out" >&2
  fi
  [[ -n "${TUNNEL_ID:-}" ]] && render_tunnel >"$root/etc/cloudflared.yml"
  render_www "$root/www"
  for p in ${PEERS:-}; do peers+=(--peer "$p"); done
  write_unit "$units/$(unit node)" node "$PREFIX/data" -- \
    "$PREFIX/bin/eidchain" node --data "$PREFIX/data" --listen "127.0.0.1:$NODE_PORT" \
    --advertise "https://$DOMAIN/chain" ${peers[@]+"${peers[@]}"}
  write_unit "$units/$(unit nginx)" nginx "$PREFIX/state/nginx" -- \
    /usr/sbin/nginx -p "$PREFIX/state/nginx" -e "$PREFIX/logs/nginx.error.log" -c "$PREFIX/etc/nginx.conf"
  if [[ -n "${TUNNEL_ID:-}" ]]; then
    write_unit "$units/$(unit tunnel)" tunnel "$PREFIX/state" -- \
      "$CLOUDFLARED" tunnel --no-autoupdate --config "$PREFIX/etc/cloudflared.yml" --metrics "$TUNNEL_METRICS" run
  fi
}

cmd_packages() {
  [[ $EUID -eq 0 ]] || die "run with sudo"
  log "nginx, rsync"
  apt-get update -q
  apt-get install -y -q ca-certificates curl gnupg nginx rsync

  log "cloudflared"
  local key fpr
  key=$(mktemp)
  curl -fsSL -o "$key" "$CF_KEY_URL"
  fpr=$(gpg --show-keys --with-colons "$key" 2>/dev/null | awk -F: '$1=="fpr" {print $10; exit}')
  [[ "$fpr" == "$CF_KEY_FPR" ]] || die "Cloudflare key fingerprint is $fpr, expected $CF_KEY_FPR"
  install -m 644 "$key" "$CF_KEYRING"
  rm -f "$key"
  echo "deb [signed-by=$CF_KEYRING] https://pkg.cloudflare.com/cloudflared any main" \
    >/etc/apt/sources.list.d/cloudflared.list
  apt-get update -q
  apt-get install -y -q cloudflared

  # The distro's nginx.service runs as root on :80 with the default site. Ours is
  # a separate unit, so that one only stays if this host serves other sites.
  if [[ -z "$(find /etc/nginx/sites-enabled -mindepth 1 ! -name default 2>/dev/null)" ]]; then
    systemctl disable --now nginx.service
    echo "   distro nginx.service disabled (only the default site was enabled)"
  else
    echo "   distro nginx.service left running: /etc/nginx/sites-enabled has other sites"
  fi
}

create_user() {
  id -u "$SERVICE_USER" >/dev/null 2>&1 && return 0
  useradd --system --user-group --no-create-home --home-dir /nonexistent \
    --shell /usr/sbin/nologin --comment "eidchain node" "$SERVICE_USER"
  echo "   user $SERVICE_USER created (system, no shell, no home)"
}

stop() {
  local s
  for s in tunnel nginx node; do
    systemctl disable --now "$(unit "$s")" 2>/dev/null || true
  done
}

cmd_install() {
  local seed=""
  if [[ "${1:-}" == "--seed" ]]; then seed=${2:?--seed needs a directory}; fi
  [[ $EUID -eq 0 ]] || die "run with sudo"
  [[ -x bin/eidchain ]] || die "build first: go build -o bin/eidchain ./cmd/eidchain"
  [[ -x /usr/sbin/nginx ]] || die "no nginx: run install.sh packages first"
  if [[ -n "${TUNNEL_ID:-}" ]]; then
    [[ -x "$CLOUDFLARED" ]] || die "no cloudflared at $CLOUDFLARED: run install.sh packages first"
    [[ -f "$PREFIX/secrets/cloudflared/$TUNNEL_ID.json" ]] ||
      die "move the tunnel credentials to $PREFIX/secrets/cloudflared/$TUNNEL_ID.json first"
  fi

  log "service user"
  create_user

  log "directories"
  mkdir -p "$PREFIX"/{bin,etc,logs,state/nginx,secrets/cloudflared}
  if [[ ! -f "$PREFIX/data/genesis.json" ]]; then
    [[ -n "$seed" ]] || die "no chain in $PREFIX/data: pass --seed DIR with genesis.json, config.json and keys/"
    [[ -f "$seed/genesis.json" ]] || die "$seed has no genesis.json"
    mkdir -p "$PREFIX/data"
    rsync -a "$seed/" "$PREFIX/data/"
    echo "   seeded $PREFIX/data from $seed"
    [[ -d "$seed/keys" ]] && echo "   the keys are now in $PREFIX/data/keys: delete $seed/keys, so no second node runs them"
  fi
  install -m 755 bin/eidchain "$PREFIX/bin/eidchain"

  log "configuration"
  local tmp
  tmp=$(mktemp -d)
  render_all "$PREFIX" "$tmp"
  # Refuse a config nginx would not start with, before anything is stopped.
  /usr/sbin/nginx -t -p "$PREFIX/state/nginx" -e "$PREFIX/logs/nginx.error.log" -c "$PREFIX/etc/nginx.conf"

  chown -R root:root "$PREFIX/bin" "$PREFIX/etc" "$PREFIX/www"
  chown -R "$SERVICE_USER:$SERVICE_USER" "$PREFIX/data" "$PREFIX/logs" "$PREFIX/state" "$PREFIX/secrets"
  chmod 700 "$PREFIX/data" "$PREFIX/secrets" "$PREFIX/secrets/cloudflared"
  [[ -d "$PREFIX/data/keys" ]] && chmod 700 "$PREFIX/data/keys" && chmod 600 "$PREFIX"/data/keys/*.key 2>/dev/null
  find "$PREFIX/secrets" -type f -exec chmod 600 {} +

  log "systemd units"
  stop
  rm -f /etc/systemd/system/"$UNIT_PREFIX"-{node,nginx,tunnel}.service
  local s
  for s in $(services); do
    install -m 644 -o root -g root "$tmp/$(unit "$s")" /etc/systemd/system/
  done
  systemctl daemon-reload
  for s in $(services); do
    systemctl enable --now "$(unit "$s")"
    echo "   $(unit "$s") started"
  done
  rm -rf "$tmp"
  echo "logs: journalctl -u '$UNIT_PREFIX-*' -f, nginx errors in $PREFIX/logs/"
}

cmd_uninstall() {
  [[ $EUID -eq 0 ]] || die "run with sudo"
  stop
  rm -f /etc/systemd/system/"$UNIT_PREFIX"-{node,nginx,tunnel}.service
  systemctl daemon-reload
  echo "services removed; $PREFIX (chain, keys, tunnel credentials) is left in place"
}

case "${1:-}" in
  render)
    dir=${2:?usage: install.sh render DIR}
    render_all "$dir" "$dir/systemd"
    echo "rendered into $dir"
    ;;
  packages) cmd_packages ;;
  install) shift; cmd_install "$@" ;;
  uninstall) cmd_uninstall ;;
  *) sed -n '2,7p' "$0" >&2; exit 2 ;;
esac
